modes.detail:
// ============ 这里的散列函数作用变了 ============
//
// 开放地址法里，散列函数算出的位置是"起点"，冲突了还要往后探测。
//
// 分离链接法里，散列函数算出的位置就是**最终归属** ——
// 它决定了这个元素挂在哪条链表上，之后就不动了。
//
// 所以散列函数的质量对分离链接法的影响更直接：
//
//   散列函数好 → 各条链表长度差不多 → 查找走几步就够
//   散列函数差 → 有的链表长、有的空着 → 长的那些退化成线性查找
//
// 这也是为什么"分布均匀"永远是散列的第一要求。
//
// ============ 复杂度 ============
//
// 查找的代价是"遍历所在链表"，所以平均是 **O(1 + α)**，
// α 是装填因子（平均每条链表的长度）。
//
// 注意这里 α 可以大于 1。α = 3 意味着平均走 3 步 —— 还是常数级，
// 但比开放地址法那种"一次数组访问"慢。

// 除留余数法
int Hash(ElementType Key, int TableSize)
{
    return Key % TableSize;
}

// 算装填因子（对分离链接法来说就是"平均链表长度"）
// 注意这里统计的是**真正的元素个数**，不含头结点。
double LoadFactor(HashTable H)
{
// 循环用
    int i;
// 元素总数
    int count = 0;
// 遍历指针
    Position P;

    for (i = 0; i < H->TableSize; i++)
    {
        for (P = H->Heads[i].Next; P != NULL; P = P->Next)
        {
            count++;
        }
    }

    return (double)count / H->TableSize;
}

