           H->TableSize, total, (double)total / H->TableSize);
    printf("  空链表 %d 条，最长链表 %d 个元素\n", empty, maxLen);
    printf("  长度分布（长度:条数）: ");
    for (i = 0; i < 10; i++)
    {
        if (dist[i] > 0)
        {
            printf("%d:%d  ", i, dist[i]);
        }
    }
    printf("\n");
    printf("  （最长链表决定最坏情况的查找代价 —— 它比平均值更值得关注）\n");
}

