#include <stdio.h>
#include <stdlib.h>

/* ======== [已给出] 模块 01 typedef ======== */

typedef int ElementType;

typedef struct LNode *PtrToLNode;
struct LNode
{
    ElementType Data;
    PtrToLNode Next;
};

typedef PtrToLNode Position;
typedef PtrToLNode List;

typedef struct TblNode *HashTable;
struct TblNode
{
    int TableSize;
    List Heads;
};

#define OK 1
#define ERROR 0
typedef int Status;

#define MAXTABLESIZE 20000

int NextPrime(int N)
{
    int i;
    int p;

    if (N <= 2)
    {
        return 2;
    }
    if (N <= 3)
    {
        return 3;
    }

    p = (N % 2 != 0) ? N : N + 1;

    while (p <= MAXTABLESIZE)
    {
        for (i = (int)(p / 2); i > 2; i--)
        {
            if (p % i == 0)
            {
                break;
            }
        }
        if (i == 2)
        {
            break;
        }
        p += 2;
    }
    return p;
}

HashTable CreateTable(int TableSize)
{
    HashTable H;
    int i;

    H = (HashTable)malloc(sizeof(struct TblNode));
    H->TableSize = NextPrime(TableSize);

    H->Heads = (List)malloc(H->TableSize * sizeof(struct LNode));

    for (i = 0; i < H->TableSize; i++)
    {
        H->Heads[i].Data = 0;
        H->Heads[i].Next = NULL;
    }

    return H;
}

void DestroyTable(HashTable H)
{
    int i;
    Position P, tmp;

    if (H == NULL)
    {
        return;
    }

    for (i = 0; i < H->TableSize; i++)
    {
        P = H->Heads[i].Next;

        while (P != NULL)
        {
            tmp = P->Next;
            free(P);
            P = tmp;
        }
    }

    free(H->Heads);
    free(H);
}

/* ======== [已给出] 模块 02 Hash ======== */

int Hash(ElementType Key, int TableSize)
{
    return Key % TableSize;
}

double LoadFactor(HashTable H)
{
    int i;
    int count = 0;
    Position P;

    for (i = 0; i < H->TableSize; i++)
    {
        for (P = H->Heads[i].Next; P != NULL; P = P->Next)
        {
            count++;
        }
    }

    return (double)count / H->TableSize;
}

/* ======== [已给出] 模块 03 Find ======== */

Position Find(HashTable H, ElementType Key)
{
    Position P;
    int pos = Hash(Key, H->TableSize);

    P = H->Heads[pos].Next;

    while (P != NULL && P->Data != Key)
    {
        P = P->Next;
    }

    return P;
}

/* ======== [已给出] 模块 04 Insert ======== */

Position Insert(HashTable H, ElementType Key)
{
    Position NewNode;
    Position P;
    int pos;

    P = Find(H, Key);
    if (P != NULL)
    {
        return P;
    }

    NewNode = (Position)malloc(sizeof(struct LNode));
    if (NewNode == NULL)
    {
        printf("内存分配失败\n");
        exit(1);
    }
    NewNode->Data = Key;

    pos = Hash(Key, H->TableSize);

    NewNode->Next = H->Heads[pos].Next;
    H->Heads[pos].Next = NewNode;

    return NewNode;
}

/* ======== [已给出] 模块 05 Delete ======== */

Status Delete(HashTable H, ElementType Key)
{
    Position Prev;
    Position P;
    int pos;

    pos = Hash(Key, H->TableSize);

    Prev = &H->Heads[pos];
    P = Prev->Next;

    while (P != NULL && P->Data != Key)
    {
        Prev = P;
        P = P->Next;
    }

    if (P == NULL)
    {
        return ERROR;
    }

    Prev->Next = P->Next;

    free(P);

    return OK;
}

/* ======== [已给出] 模块 06 PrintTable ======== */

void PrintTable(HashTable H)
{
    int i;
    Position P;

    for (i = 0; i < H->TableSize; i++)
    {
        printf("  [%2d] ", i);
        P = H->Heads[i].Next;

        if (P == NULL)
        {
            printf("(空)");
        }

        while (P != NULL)
        {
            printf("%d", P->Data);
            if (P->Next != NULL)
            {
                printf(" → ");
            }
            P = P->Next;
        }
        printf("\n");
    }
}

void PrintStats(HashTable H)
{
    int i;
    Position P;
    int len;
    int maxLen = 0;
    int empty = 0;
    int total = 0;
    int dist[10];

    for (i = 0; i < 10; i++)
    {
        dist[i] = 0;
    }

    for (i = 0; i < H->TableSize; i++)
    {
        len = 0;
        for (P = H->Heads[i].Next; P != NULL; P = P->Next)
        {
            len++;
        }

        total += len;
        if (len > maxLen)
        {
            maxLen = len;
        }
        if (len == 0)
        {
            empty++;
        }
        if (len < 10)
        {
            dist[len]++;
        }
    }

    printf("  表长 = %d，元素 = %d，装填因子 = %.2f\n",
           H->TableSize, total, (double)total / H->TableSize);
    printf("  空链表 %d 条，最长链表 %d 个元素\n", empty, maxLen);
    printf("  长度分布（长度:条数）: ");
    for (i = 0; i < 10; i++)
    {
        if (dist[i] > 0)
        {
            printf("%d:%d  ", i, dist[i]);
        }
    }
    printf("\n");
    printf("  （最长链表决定最坏情况的查找代价 —— 它比平均值更值得关注）\n");
}

