#include <stdio.h>
#include <stdlib.h>


// 元素类型
typedef int ElementType;

// 链表结点
typedef struct LNode *PtrToLNode;
struct LNode
{
// 存的关键字（头结点这个字段不用）
    ElementType Data;
// 下一个结点
    PtrToLNode Next;
};

// 位置（就是结点指针）
typedef PtrToLNode Position;
// 链表
typedef PtrToLNode List;

// 散列表
typedef struct TblNode *HashTable;
struct TblNode
{
// 表长（素数）
    int TableSize;
// 链表头数组
    List Heads;
};

// 状态码
#define OK 1
#define ERROR 0
typedef int Status;

// 表的最大容量
#define MAXTABLESIZE 20000

// 取不小于 N 的下一个素数
int NextPrime(int N)
{
// 循环用
    int i;
// 待检查
    int p;

    if (N <= 2)
    {
        return 2;
    }
    if (N <= 3)
    {
        return 3;
    }

// 从 N 本身开始（N 是偶数就先加一到奇数）
    p = (N % 2 != 0) ? N : N + 1;

    while (p <= MAXTABLESIZE)
    {
        for (i = (int)(p / 2); i > 2; i--)
        {
            if (p % i == 0)
            {
                break;
            }
        }
        if (i == 2)
        {
            break;
        }
        p += 2;
    }
    return p;
}

// 建一个空表
HashTable CreateTable(int TableSize)
{
// 表
    HashTable H;
// 循环用
    int i;

// 分配表结构
    H = (HashTable)malloc(sizeof(struct TblNode));
// 表长取素数
    H->TableSize = NextPrime(TableSize);

// 分配链表头数组
    H->Heads = (List)malloc(H->TableSize * sizeof(struct LNode));

// 每格的 Data 不用，Next 置空
    for (i = 0; i < H->TableSize; i++)
    {
// 头结点的数据字段不用
        H->Heads[i].Data = 0;
// 链表先空着
        H->Heads[i].Next = NULL;
    }

    return H;
}

// 释放整张表
void DestroyTable(HashTable H)
{
// 循环用
    int i;
// 遍历指针和下一个
    Position P, tmp;

    if (H == NULL)
    {
        return;
    }

// 逐条链表释放
    for (i = 0; i < H->TableSize; i++)
    {
        P = H->Heads[i].Next;

        while (P != NULL)
        {
// 先记住下一个
            tmp = P->Next;
// 再释放当前
            free(P);
// 往后走
            P = tmp;
        }
    }

// 先 free 头数组
    free(H->Heads);
// 再 free 表结构
    free(H);
}


// 除留余数法
int Hash(ElementType Key, int TableSize)
{
    return Key % TableSize;
}

// 算装填因子（对分离链接法来说就是"平均链表长度"）
double LoadFactor(HashTable H)
{
// 循环用
    int i;
// 元素总数
    int count = 0;
// 遍历指针
    Position P;

    for (i = 0; i < H->TableSize; i++)
    {
        for (P = H->Heads[i].Next; P != NULL; P = P->Next)
        {
            count++;
        }
    }

    return (double)count / H->TableSize;
}


// 查找 Key，返回结点位置；没找到返回 NULL
Position Find(HashTable H, ElementType Key)
{
// 遍历指针
    Position P;
// 这个键该挂在哪条链表上
    int pos = Hash(Key, H->TableSize);

// 从虚拟头结点的下一个开始
    P = H->Heads[pos].Next;

// 顺着链表找
    while (P != NULL && P->Data != Key)
    {
        P = P->Next;
    }

// 返回 P（找到就是结点，没找到就是 NULL）
    return P;
}


// 插入 Key；已存在则什么都不做
Position Insert(HashTable H, ElementType Key)
{
// 新结点
    Position NewNode;
// 已有的结点
    Position P;
// 该挂在哪条链上
    int pos;

// ① 先查重
    P = Find(H, Key);
    if (P != NULL)
    {
// 已经存在，直接返回
        return P;
    }

// ② 造新结点
    NewNode = (Position)malloc(sizeof(struct LNode));
    if (NewNode == NULL)
    {
        printf("内存分配失败\n");
        exit(1);
    }
    NewNode->Data = Key;

// 算出该挂哪条链
    pos = Hash(Key, H->TableSize);

// ③ 头插到那条链上
    NewNode->Next = H->Heads[pos].Next;
    H->Heads[pos].Next = NewNode;

// 返回新结点
    return NewNode;
}


Status Delete(HashTable H, ElementType Key)
{
// 前驱结点（从虚拟头开始）
    Position Prev;
// 当前结点
    Position P;
// 该在哪条链上
    int pos;

// 算出链表位置
    pos = Hash(Key, H->TableSize);

// 从虚拟头结点开始
    Prev = &H->Heads[pos];
    P = Prev->Next;

// 找待删结点
    while (P != NULL && P->Data != Key)
    {
// 前驱和当前一起往后走
        Prev = P;
        P = P->Next;
    }

// 走到尾都没找到
    if (P == NULL)
    {
        return ERROR;
    }

// 把它从链上绕过
    Prev->Next = P->Next;

// 释放
    free(P);

// 成功
    return OK;
}


// 打印散列表的每一条链表
void PrintTable(HashTable H)
{
// 循环用
    int i;
// 遍历指针
    Position P;

    for (i = 0; i < H->TableSize; i++)
    {
        printf("  [%2d] ", i);
        P = H->Heads[i].Next;

// 链表空着
        if (P == NULL)
        {
            printf("(空)");
        }

// 打印链表上的元素
        while (P != NULL)
        {
            printf("%d", P->Data);
            if (P->Next != NULL)
            {
                printf(" → ");
            }
            P = P->Next;
        }
        printf("\n");
    }
}

// 统计链表长度的分布
void PrintStats(HashTable H)
{
// 循环用
    int i;
// 遍历指针
    Position P;
// 当前链表长度
    int len;
// 最长链表
    int maxLen = 0;
// 空链表的条数
    int empty = 0;
// 元素总数
    int total = 0;
// 长度分布的计数（长度 0~9）
    int dist[10];

// 清零
    for (i = 0; i < 10; i++)
    {
        dist[i] = 0;
    }

// 逐条统计
    for (i = 0; i < H->TableSize; i++)
    {
        len = 0;
        for (P = H->Heads[i].Next; P != NULL; P = P->Next)
        {
            len++;
        }

        total += len;
        if (len > maxLen)
        {
            maxLen = len;
        }
        if (len == 0)
        {
            empty++;
        }
        if (len < 10)
        {
            dist[len]++;
        }
    }

// 输出
    printf("  表长 = %d，元素 = %d，装填因子 = %.2f\n",
           H->TableSize, total, (double)total / H->TableSize);
    printf("  空链表 %d 条，最长链表 %d 个元素\n", empty, maxLen);
    printf("  长度分布（长度:条数）: ");
    for (i = 0; i < 10; i++)
    {
        if (dist[i] > 0)
        {
            printf("%d:%d  ", i, dist[i]);
        }
    }
    printf("\n");
    printf("  （最长链表决定最坏情况的查找代价 —— 它比平均值更值得关注）\n");
}


// 主函数
int main(void)
{
// 一批都会散列到 0 号桶的关键字
    static const ElementType keys[] = { 11, 22, 33, 44, 55, 66, 77, 88 };
